<template><AppLayout page-title="Mon dossier médical"><div v-if="error" class="alert alert-error">{{error}}</div><div v-else-if="loading" class="loading-overlay"><div class="spinner"/></div><template v-else><div class="grid-2"><section class="card"><h3>Informations médicales</h3><div class="field"><b>Allergies</b><p>{{arr(dossier?.allergies)}}</p></div><div class="field"><b>Maladies chroniques</b><p>{{arr(dossier?.chronic_conditions)}}</p></div><div class="field"><b>Antécédents</b><p>{{dossier?.past_medical_history||'Non renseigné'}}</p></div><div class="field"><b>Antécédents chirurgicaux</b><p>{{dossier?.surgical_history||'Non renseigné'}}</p></div><div class="field"><b>Antécédents familiaux</b><p>{{dossier?.family_history||'Non renseigné'}}</p></div></section><section class="card"><h3>Historique médical</h3><div v-if="entries.length===0" class="empty-state"><div class="empty-icon">📋</div><div>Aucune entrée disponible.</div></div><div v-for="e in entries" :key="e.id" class="timeline-item"><b>{{e.title}}</b><small>{{new Date(e.created_at).toLocaleDateString('fr-FR')}}</small><p>{{e.content}}</p></div></section></div></template></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore();const loading=ref(true),error=ref('');const dossier=ref<any>(null),entries=ref<any[]>([]);const arr=(v:any)=>Array.isArray(v)&&v.length?v.join(', '):'Non renseigné';onMounted(async()=>{if(!auth.user)return;const r=await supabase.from('medical_dossiers').select('*').eq('patient_id',auth.user.id).single();if(r.error&&r.error.code!=='PGRST116')error.value=r.error.message;dossier.value=r.data;if(r.data){const e=await supabase.from('medical_record_entries').select('*').eq('dossier_id',r.data.id).order('created_at',{ascending:false});entries.value=e.data||[];}loading.value=false})</script>